from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # used[employee][year] = number of leave days used
        self._used: dict[str, dict[int, int]] = {}

    def _is_working_day(self, d: date) -> bool:
        return d.weekday() < 5 and d not in self.holidays

    def _count_days(self, start: date, end: date) -> int:
        count = 0
        d = start
        while d <= end:
            if self._is_working_day(d):
                count += 1
            d += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date is before start date")
        if (start - today).days < 3:
            raise ValueError("Requests must be made at least 3 days in advance")

        days_needed = self._count_days(start, end)

        # A request spanning multiple years: check each year's remaining
        # For simplicity, attribute days to the years they fall in and verify each year.
        yearly: dict[int, int] = {}
        d = start
        while d <= end:
            if self._is_working_day(d):
                yearly[d.year] = yearly.get(d.year, 0) + 1
            d += timedelta(days=1)

        for year, needed in yearly.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient leave days remaining in {year}"
                )

        emp_used = self._used.setdefault(employee, {})
        for year, needed in yearly.items():
            emp_used[year] = emp_used.get(year, 0) + needed

        return days_needed

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get(employee, {}).get(year, 0)
        return self.days_per_year - used
